# -*- coding: utf-8 -*-
"""Bổ sung 1–2 câu RU thực chất cho presentation_long_ru của các điểm Quảng Ninh
mới thêm để độ dài tiệm cận ~180 từ (đồng bộ chuẩn nhà). Idempotent theo dấu câu."""
import json, os, re

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
F = os.path.join(ROOT, "data", "regions", "vn-quang-ninh.json")

